)
$canonical = ($lines -join "`n") + "`n"
$hmac = New-Object System.Security.Cryptography.HMACSHA256
$hmac.Key = [Text.Encoding]::UTF8.GetBytes($apiKey)
hash = [BitConverter]::ToString($hmac.ComputeHash([Text.Encoding]::UTF8.GetBytes($canonical))).Replace('-','')
[pscustomobject]@{ SignatureMatch = ($hash -eq $sigValue); Computed = $hash; Expected = $sigValue; CanonicalLen = $canonical.Length; ApiKeyLen = $apiKey.Length; Port = $port; BaseUrl = $baseUrl; Workspace = $workspace }"}}

