    /// assert edge so a held RESTORE does not re-fire until release+press.
    /// </remarks>
    public void SetRestore(bool pressed)
    {
        if (pressed == _restoreKeyPressed)
            return;

        _restoreKeyPressed = pressed;
        if (_nmiLine is null)
            return;

        if (pressed)
            _nmiLine.Assert(this);
        else
